def runcheck(name,code,expected_error=None,prefix='',predicate=None):
 scope={}; out=io.StringIO();err=None
 try:
  with contextlib.redirect_stdout(out):
   if prefix:exec(prefix,scope)
   exec(code,scope)
 except Exception as e:err=type(e).__name__+': '+str(e)
 passed=(err is not None and err.startswith(expected_error+':')) if expected_error else err is None and (predicate(scope,out.getvalue()) if predicate else True)
 checks.append(dict(id=name,code=code,prefix=prefix,expectedError=expected_error,actualError=err,stdout=out.getvalue(),passed=bool(passed),verificationKind='author_executable_check_not_independent_review',pythonVersion=sys.version.split()[0]))
 assert passed,(name,err,out.getvalue())
 return scope
